def get_page(integration_id, notion_page_id, **_extra):
    import json, os, datetime, time, re, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    integrations = _load("integrations.json")
    pages = _load("pages.json")
    reqlogs = _load("request_logs.json")
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(success, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, payload=None):
        dur = int(max(0, (time.time() - t0) * 1000))
        reqlogs.append({
            "id": _new_id("nia_rlg"),
            "integration_id": integration_id if isinstance(integration_id, str) else "",
            "tool_name": "get_page",
            "request_payload": payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": dur,
            "created_at": now,
            "updated_at": now
        })
        _save("request_logs.json", reqlogs)

    def _rate_limit_check():
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqlogs:
            if r.get("integration_id") != integration_id:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt < 3

    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, notion_endpoint="/v1/pages/{id}", error_code="VALIDATION_ERROR",
             error_message="integration_id is missing or invalid",
             payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "integration_id is missing or invalid")

    if not isinstance(notion_page_id, str) or not notion_page_id.strip():
        _log(False, notion_endpoint="/v1/pages/{id}", error_code="VALIDATION_ERROR",
             error_message="notion_page_id is missing or invalid",
             payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "notion_page_id is missing or invalid")

    integ = next((i for i in integrations if i.get("id") == integration_id), None)
    if not integ:
        _log(False, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=401, error_code="UNAUTHORIZED",
             error_message="Unknown integration_id",
             payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    # Reads are allowed even if disabled/revoked per business rule (only mutating tools rejected).
    if not _rate_limit_check():
        _log(False, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=429, error_code="RATE_LIMIT",
             error_message="Rate limited",
             payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("RATE_LIMIT", "Rate limited", retry_after_ms=1000)

    # Accept either local internal id or notion_page_id
    page_row = next((p for p in pages if p.get("integration_id") == integration_id and (p.get("notion_page_id") == notion_page_id or p.get("id") == notion_page_id)), None)

    # If missing, emulate fetch-from-Notion: if cannot be found locally, treat as NOT_FOUND.
    if not page_row:
        _log(False, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=404, error_code="NOT_FOUND",
             error_message="Page not found",
             payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("NOT_FOUND", "Page not found")

    # If stale (no last_synced_at), refresh minimal fields
    updated = False
    if not page_row.get("last_synced_at"):
        page_row["last_synced_at"] = now
        page_row["notion_last_edited_time"] = page_row.get("notion_last_edited_time") or now
        page_row["updated_at"] = now
        updated = True

    if updated:
        _save("pages.json", pages)

    notion_page_obj = {
        "object": "page",
        "id": page_row.get("notion_page_id"),
        "created_time": page_row.get("notion_created_time"),
        "last_edited_time": page_row.get("notion_last_edited_time"),
        "archived": bool(page_row.get("archived")),
        "parent": {"type": page_row.get("parent_type")},
        "properties": page_row.get("properties") or {},
        "icon": page_row.get("icon"),
        "cover": page_row.get("cover")
    }
    pt = page_row.get("parent_type")
    if pt in ("page", "database"):
        notion_page_obj["parent"][pt] = {"id": page_row.get("parent_notion_id")}
    elif pt == "workspace":
        notion_page_obj["parent"]["workspace"] = True

    _log(True, notion_endpoint=f"/v1/pages/{page_row.get('notion_page_id')}", notion_http_status=200,
         payload={"integration_id": integration_id, "notion_page_id": notion_page_id})

    return {"page": notion_page_obj, "mirror": page_row, "request": {"integration_id": integration_id}}

def update_page(integration_id, notion_page_id, properties=None, archived=None, icon=None, cover=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        num = int.from_bytes(os.urandom(16), "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    integrations = _load("integrations.json")
    pages = _load("pages.json")
    todos = _load("todos.json")
    reqlogs = _load("request_logs.json")

    # Rate limiting: allow reasonable throughput; previous code was too strict/buggy.
    # Implementation-level limit: 60 calls / 1s / integration across tools.
    def _rate_limited(integration_id_val):
        if not isinstance(integration_id_val, str) or not integration_id_val:
            return False
        cutoff = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqlogs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_id") != integration_id_val:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt >= 60

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        reqlogs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "update_page",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", reqlogs)

    # Validate inputs
    if not isinstance(integration_id, str) or not integration_id:
        _log(False, integration_id, error_code="validation_error", error_message="integration_id must be a non-empty string", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "integration_id must be a non-empty string")
    if not isinstance(notion_page_id, str) or not notion_page_id:
        _log(False, integration_id, error_code="validation_error", error_message="notion_page_id must be a non-empty string", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "notion_page_id must be a non-empty string")
    if properties is not None and not isinstance(properties, dict):
        _log(False, integration_id, error_code="validation_error", error_message="properties must be an object", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "properties must be an object")
    if icon is not None and not isinstance(icon, dict):
        _log(False, integration_id, error_code="validation_error", error_message="icon must be an object", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "icon must be an object")
    if cover is not None and not isinstance(cover, dict):
        _log(False, integration_id, error_code="validation_error", error_message="cover must be an object", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "cover must be an object")
    if archived is not None and not isinstance(archived, bool):
        _log(False, integration_id, error_code="validation_error", error_message="archived must be a boolean", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "archived must be a boolean")

    # Resolve integration context
    integ = None
    for r in integrations:
        if isinstance(r, dict) and r.get("id") == integration_id:
            integ = r
            break
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    # Mutating tools must be rejected for disabled/revoked
    if integ.get("status") in ("disabled", "revoked"):
        _log(False, integration_id, error_code="unauthorized", error_message="Integration is disabled or revoked; mutating tools are not allowed", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Integration is disabled or revoked; mutating tools are not allowed")

    if _rate_limited(integration_id):
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=429, error_code="rate_limited", error_message="Notion rate limit backoff", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Find existing local page mirror by (integration_id, notion_page_id) OR by internal id if user passed that by mistake
    page = None
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("integration_id") == integration_id and (p.get("notion_page_id") == notion_page_id or p.get("id") == notion_page_id):
            page = p
            break

    # If missing: allow update by creating a minimal mirror "as if fetched from Notion",
    # because the store is a cache and real service can operate even if cache is stale/missing.
    if not page:
        # Upsert minimal mirror row (cannot actually call Notion offline; treat as successful Notion update)
        new_id = _gen_id("nia_pag_")
        page = {
            "id": new_id,
            "integration_id": integration_id,
            "notion_page_id": notion_page_id,
            "parent_type": "workspace",
            "parent_notion_id": None,
            "in_database_notion_id": None,
            "title_plaintext": None,
            "icon": None,
            "cover": None,
            "properties": {},
            "archived": False,
            "status": "active",
            "notion_created_time": None,
            "notion_last_edited_time": now,
            "last_synced_at": now,
            "last_sync_error": None,
            "created_at": now,
            "updated_at": now,
        }
        pages.append(page)

    # Business rule: update_page must only operate on pages.status != 'deleted_remote'
    if page.get("status") == "deleted_remote":
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=404, error_code="deleted_remote", error_message="Cannot update a page marked deleted_remote", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("INVALID_TRANSITION", "Cannot update a page marked deleted_remote")

    # Apply updates (simulate successful Notion update)
    merged_props = page.get("properties")
    if not isinstance(merged_props, dict):
        merged_props = {}
    if properties is not None:
        for k, v in properties.items():
            merged_props[k] = v
    page["properties"] = merged_props

    if icon is not None:
        page["icon"] = icon
    if cover is not None:
        page["cover"] = cover

    if archived is not None:
        page["archived"] = bool(archived)
        # Must keep status consistent with archived flag
        page["status"] = "archived" if page["archived"] else "active"

    page["notion_last_edited_time"] = now
    page["last_synced_at"] = now
    page["last_sync_error"] = None
    page["updated_at"] = now

    # If this page is a todo row, reflect archive/restore in todos
    changed_todos = False
    for td in todos:
        if not isinstance(td, dict):
            continue
        if td.get("integration_id") != integration_id:
            continue
        if td.get("page_id") == page.get("id") or td.get("notion_page_id") == page.get("notion_page_id"):
            if page.get("archived"):
                td["archived"] = True
                # lifecycle transition to archived always allowed from open/completed per schema
                td["status"] = "archived"
            else:
                td["archived"] = False
                # restore to open unless explicitly completed=true (constraint)
                if td.get("completed") is True:
                    td["status"] = "completed"
                else:
                    td["status"] = "open"
            td["updated_at"] = now
            changed_todos = True

    _save("pages.json", pages)
    if changed_todos:
        _save("todos.json", todos)

    _log(True, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=200, request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
    return {"object": "page", "page": page}

def archive_page(integration_id, notion_page_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        num = int.from_bytes(b, "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "archive_page",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", logs)

    # --- validate inputs ---
    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, integration_id if isinstance(integration_id, str) else "", notion_endpoint="/v1/pages/{id}",
             error_code="validation_error", error_message="integration_id is missing or malformed",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "integration_id is missing or malformed")

    if not isinstance(notion_page_id, str) or not notion_page_id.strip():
        _log(False, integration_id, notion_endpoint="/v1/pages/{id}",
             error_code="validation_error", error_message="notion_page_id is missing or invalid",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "notion_page_id is missing or invalid")

    integrations = _load("integrations.json")
    if isinstance(integrations, dict) and "rows" in integrations:
        # tolerate digest-shaped file; treat as empty rows
        integrations = []
    if not isinstance(integrations, list):
        integrations = []

    pages = _load("pages.json")
    if isinstance(pages, dict) and "rows" in pages:
        pages = []
    if not isinstance(pages, list):
        pages = []

    todos = _load("todos.json")
    if isinstance(todos, dict) and "rows" in todos:
        todos = []
    if not isinstance(todos, list):
        todos = []

    # resolve integration
    integ = next((r for r in integrations if isinstance(r, dict) and r.get("id") == integration_id), None)
    if not integ:
        _log(False, integration_id, notion_endpoint="/v1/pages/{id}", error_code="unauthorized",
             error_message="Unknown integration_id",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    # mutating tools rejected when disabled/revoked
    if integ.get("status") in ("disabled", "revoked"):
        _log(False, integration_id, notion_endpoint="/v1/pages/{id}", error_code="unauthorized",
             error_message="Integration is disabled or revoked; mutating operations are not permitted",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Integration is disabled or revoked; mutating operations are not permitted")

    # find page by notion_page_id (or internal id as fallback)
    page = None
    for r in pages:
        if not isinstance(r, dict):
            continue
        if r.get("integration_id") != integration_id:
            continue
        if r.get("notion_page_id") == notion_page_id or r.get("id") == notion_page_id:
            page = r
            break

    if not page:
        # Read tools would fetch from Notion; this mutating tool requires the page to be known/shared.
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=404,
             error_code="object_not_found", error_message="Page does not exist or is not shared with the integration",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("NOT_FOUND", "Page does not exist or is not shared with the integration")

    if page.get("status") == "deleted_remote":
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{page.get('notion_page_id')}", notion_http_status=409,
             error_code="invalid_transition", error_message="Cannot archive a page marked deleted_remote",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("INVALID_TRANSITION", "Cannot archive a page marked deleted_remote")

    if bool(page.get("archived")) is True or page.get("status") == "archived":
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{page.get('notion_page_id')}", notion_http_status=409,
             error_code="conflict", error_message="Page is already archived",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("CONFLICT", "Page is already archived")

    # perform local mirror update (simulates successful Notion archive)
    page["archived"] = True
    page["status"] = "archived"
    page["updated_at"] = now
    page["notion_last_edited_time"] = now
    page["last_synced_at"] = now
    page["last_sync_error"] = None

    # reflect in todos if page is backing a todo row
    changed_todos = 0
    for td in todos:
        if not isinstance(td, dict):
            continue
        if td.get("integration_id") != integration_id:
            continue
        if td.get("page_id") == page.get("id") or td.get("notion_page_id") == page.get("notion_page_id"):
            td["archived"] = True
            td["status"] = "archived"
            td["updated_at"] = now
            changed_todos += 1

    _save("pages.json", pages)
    if changed_todos:
        _save("todos.json", todos)

    _log(True, integration_id, notion_endpoint=f"/v1/pages/{page.get('notion_page_id')}", notion_http_status=200,
         request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})

    return {"page": page}

def restore_page(integration_id, notion_page_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        num = int.from_bytes(b, "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "restore_page",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", logs)

    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, integration_id if isinstance(integration_id, str) else "", notion_endpoint="/v1/pages/{id}",
             error_code="validation_error", error_message="integration_id is missing or malformed",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "integration_id is missing or malformed")

    if not isinstance(notion_page_id, str) or not notion_page_id.strip():
        _log(False, integration_id, notion_endpoint="/v1/pages/{id}",
             error_code="validation_error", error_message="notion_page_id is missing or invalid",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("VALIDATION_ERROR", "notion_page_id is missing or invalid")

    integrations = _load("integrations.json")
    if isinstance(integrations, dict) and "rows" in integrations:
        integrations = []
    if not isinstance(integrations, list):
        integrations = []

    pages = _load("pages.json")
    if isinstance(pages, dict) and "rows" in pages:
        pages = []
    if not isinstance(pages, list):
        pages = []

    todos = _load("todos.json")
    if isinstance(todos, dict) and "rows" in todos:
        todos = []
    if not isinstance(todos, list):
        todos = []

    integ = next((r for r in integrations if isinstance(r, dict) and r.get("id") == integration_id), None)
    if not integ:
        _log(False, integration_id, notion_endpoint="/v1/pages/{id}", error_code="unauthorized",
             error_message="Unknown integration_id",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    if integ.get("status") in ("disabled", "revoked"):
        _log(False, integration_id, notion_endpoint="/v1/pages/{id}", error_code="unauthorized",
             error_message="Integration is disabled or revoked; mutating operations are not permitted",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("UNAUTHORIZED", "Integration is disabled or revoked; mutating operations are not permitted")

    page = None
    for r in pages:
        if not isinstance(r, dict):
            continue
        if r.get("integration_id") != integration_id:
            continue
        if r.get("notion_page_id") == notion_page_id or r.get("id") == notion_page_id:
            page = r
            break

    if not page:
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}", notion_http_status=404,
             error_code="object_not_found", error_message="Page does not exist or is not shared with the integration",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("NOT_FOUND", "Page does not exist or is not shared with the integration")

    if page.get("status") == "deleted_remote":
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{page.get('notion_page_id')}", notion_http_status=409,
             error_code="invalid_transition", error_message="Cannot restore a page marked deleted_remote",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("INVALID_TRANSITION", "Cannot restore a page marked deleted_remote")

    if bool(page.get("archived")) is False and page.get("status") == "active":
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{page.get('notion_page_id')}", notion_http_status=409,
             error_code="conflict", error_message="Page is not archived",
             request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})
        return _err("CONFLICT", "Page is not archived")

    # restore
    page["archived"] = False
    page["status"] = "active"
    page["updated_at"] = now
    page["notion_last_edited_time"] = now
    page["last_synced_at"] = now
    page["last_sync_error"] = None

    changed_todos = 0
    for td in todos:
        if not isinstance(td, dict):
            continue
        if td.get("integration_id") != integration_id:
            continue
        if td.get("page_id") == page.get("id") or td.get("notion_page_id") == page.get("notion_page_id"):
            td["archived"] = False
            # if completed flag true -> completed else open
            if bool(td.get("completed")):
                td["status"] = "completed"
            else:
                td["status"] = "open"
            td["updated_at"] = now
            changed_todos += 1

    _save("pages.json", pages)
    if changed_todos:
        _save("todos.json", todos)

    _log(True, integration_id, notion_endpoint=f"/v1/pages/{page.get('notion_page_id')}", notion_http_status=200,
         request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id})

    return {"page": page}

def get_page_property(integration_id, notion_page_id, property_id, start_cursor=None, page_size=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        num = int.from_bytes(os.urandom(16), "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    integrations = _load("integrations.json")
    pages = _load("pages.json")
    reqlogs = _load("request_logs.json")

    def _rate_limited(integration_id_val):
        cutoff = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqlogs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_id") != integration_id_val:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt >= 120  # reads get a higher allowance

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        reqlogs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "get_page_property",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", reqlogs)

    # Validate
    if not isinstance(integration_id, str) or not integration_id:
        _log(False, integration_id, error_code="validation_error", error_message="integration_id must be a non-empty string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "integration_id must be a non-empty string")
    if not isinstance(notion_page_id, str) or not notion_page_id:
        _log(False, integration_id, error_code="validation_error", error_message="notion_page_id must be a non-empty string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "notion_page_id must be a non-empty string")
    if not isinstance(property_id, str) or not property_id:
        _log(False, integration_id, error_code="validation_error", error_message="property_id must be a non-empty string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "property_id must be a non-empty string")
    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log(False, integration_id, error_code="validation_error", error_message="page_size must be between 1 and 100", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log(False, integration_id, error_code="validation_error", error_message="start_cursor must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "start_cursor must be a string")

    integ = None
    for r in integrations:
        if isinstance(r, dict) and r.get("id") == integration_id:
            integ = r
            break
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id", request_payload={"integration_id": integration_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    if _rate_limited(integration_id):
        _log(False, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}/properties/{property_id}", notion_http_status=429, error_code="rate_limited", error_message="Notion rate limit backoff", request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id, "property_id": property_id})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Locate page (by notion id or internal id)
    page = None
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("integration_id") == integration_id and (p.get("notion_page_id") == notion_page_id or p.get("id") == notion_page_id):
            page = p
            break

    # If missing, create minimal mirror (as if fetched from Notion). Do not error.
    if not page:
        page = {
            "id": _gen_id("nia_pag_"),
            "integration_id": integration_id,
            "notion_page_id": notion_page_id,
            "parent_type": "workspace",
            "parent_notion_id": None,
            "in_database_notion_id": None,
            "title_plaintext": None,
            "icon": None,
            "cover": None,
            "properties": {},
            "archived": False,
            "status": "active",
            "notion_created_time": None,
            "notion_last_edited_time": None,
            "last_synced_at": now,
            "last_sync_error": None,
            "created_at": now,
            "updated_at": now,
        }
        pages.append(page)
        _save("pages.json", pages)

    props = page.get("properties")
    if not isinstance(props, dict):
        props = {}
        page["properties"] = props

    # Support property lookup by exact key, or by matching nested property "id" fields in Notion-like property objects
    val = None
    if property_id in props:
        val = props.get(property_id)
    else:
        for k, v in props.items():
            if isinstance(v, dict) and v.get("id") == property_id:
                val = v
                property_id = k  # normalize to name
                break

    # If still missing, return empty property item envelope (real API would 404; this backend supports name/id flexibility but should not claim page missing)
    if val is None:
        page["last_synced_at"] = now
        page["updated_at"] = now
        _save("pages.json", pages)
        _log(True, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}/properties/{property_id}", notion_http_status=200, request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id, "property_id": property_id})
        return {
            "object": "property_item",
            "property_id": property_id,
            "type": "unknown",
            "results": [],
            "has_more": False,
            "next_cursor": None
        }

    # If property is a list-like structure, paginate. Accept flexible shapes.
    results = None
    next_cursor = None
    has_more = False

    if isinstance(val, dict) and isinstance(val.get("results"), list):
        results = val.get("results")
    elif isinstance(val, list):
        results = val
    else:
        # non-paginated single value
        page["last_synced_at"] = now
        page["updated_at"] = now
        _save("pages.json", pages)
        _log(True, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}/properties/{property_id}", notion_http_status=200, request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id, "property_id": property_id})
        return {"object": "property_item", "property_id": property_id, "value": val, "has_more": False, "next_cursor": None}

    # paginate list results using start_cursor as an integer offset or opaque token "idx:<n>"
    offset = 0
    if start_cursor:
        if start_cursor.startswith("idx:"):
            try:
                offset = int(start_cursor.split(":", 1)[1])
            except Exception:
                offset = 0
        else:
            # accept arbitrary cursor strings; cannot interpret -> start at 0 (do not error; schema says string)
            offset = 0
    if offset < 0:
        offset = 0

    slice_ = results[offset: offset + page_size]
    if offset + page_size < len(results):
        has_more = True
        next_cursor = f"idx:{offset + page_size}"

    page["last_synced_at"] = now
    page["updated_at"] = now
    _save("pages.json", pages)

    _log(True, integration_id, notion_endpoint=f"/v1/pages/{notion_page_id}/properties/{property_id}", notion_http_status=200, request_payload={"integration_id": integration_id, "notion_page_id": notion_page_id, "property_id": property_id})
    return {
        "object": "list",
        "property_id": property_id,
        "results": slice_,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def add_todo(integration_id, database_id, title, description=None, due_at=None, priority=None, tags=None, assignees=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        num = int.from_bytes(b, "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "add_todo",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, "due_at must be an ISO-8601 datetime string"
        try:
            dt = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc)
            # enforce >= 2000-01-01T00:00:00Z
            if dt < datetime.datetime(2000, 1, 1, tzinfo=datetime.timezone.utc):
                return None, "due_at must be >= 2000-01-01T00:00:00Z"
            return dt.isoformat().replace("+00:00", "Z"), None
        except Exception:
            return None, "due_at must be an ISO-8601 datetime string"

    # validate
    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, integration_id if isinstance(integration_id, str) else "", error_code="validation_error",
             error_message="integration_id is missing or malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("VALIDATION_ERROR", "integration_id is missing or malformed")
    if not isinstance(database_id, str) or not re.match(r"^nia_dbs_[0-9A-HJKMNP-TV-Z]{17,}$", database_id):
        _log(False, integration_id, error_code="validation_error",
             error_message="database_id is missing or malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("VALIDATION_ERROR", "database_id is missing or malformed")
    if not isinstance(title, str) or not title.strip():
        _log(False, integration_id, error_code="validation_error",
             error_message="title is required and must be non-empty",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("VALIDATION_ERROR", "title is required and must be non-empty")
    if priority is not None and priority not in ("low", "medium", "high", "urgent"):
        _log(False, integration_id, error_code="validation_error",
             error_message="priority must be one of low, medium, high, urgent",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title, "priority": priority})
        return _err("VALIDATION_ERROR", "priority must be one of low, medium, high, urgent")
    if tags is not None and (not isinstance(tags, list) or any(not isinstance(x, str) for x in tags)):
        _log(False, integration_id, error_code="validation_error",
             error_message="tags must be an array of strings",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title, "tags": tags})
        return _err("VALIDATION_ERROR", "tags must be an array of strings")
    if assignees is not None and (not isinstance(assignees, list) or any(not isinstance(x, str) for x in assignees)):
        _log(False, integration_id, error_code="validation_error",
             error_message="assignees must be an array of strings",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title, "assignees": assignees})
        return _err("VALIDATION_ERROR", "assignees must be an array of strings")

    due_iso, due_err = _parse_dt(due_at)
    if due_err:
        _log(False, integration_id, error_code="validation_error", error_message=due_err,
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title, "due_at": due_at})
        return _err("VALIDATION_ERROR", due_err)

    integrations = _load("integrations.json")
    if isinstance(integrations, dict) and "rows" in integrations:
        integrations = []
    if not isinstance(integrations, list):
        integrations = []

    databases = _load("databases.json")
    if isinstance(databases, dict) and "rows" in databases:
        databases = []
    if not isinstance(databases, list):
        databases = []

    pages = _load("pages.json")
    if isinstance(pages, dict) and "rows" in pages:
        pages = []
    if not isinstance(pages, list):
        pages = []

    todos = _load("todos.json")
    if isinstance(todos, dict) and "rows" in todos:
        todos = []
    if not isinstance(todos, list):
        todos = []

    integ = next((r for r in integrations if isinstance(r, dict) and r.get("id") == integration_id), None)
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("UNAUTHORIZED", "Unknown integration_id")
    if integ.get("status") in ("disabled", "revoked"):
        _log(False, integration_id, error_code="unauthorized",
             error_message="Integration is disabled or revoked; mutating operations are not permitted",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("UNAUTHORIZED", "Integration is disabled or revoked; mutating operations are not permitted")

    db = next((r for r in databases if isinstance(r, dict) and r.get("id") == database_id and r.get("integration_id") == integration_id), None)
    if not db:
        _log(False, integration_id, error_code="not_found", error_message="Database not found",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("NOT_FOUND", "Database not found")
    if db.get("status") == "deleted_remote":
        _log(False, integration_id, error_code="invalid_transition", error_message="Cannot add todo to a deleted_remote database",
             request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})
        return _err("INVALID_TRANSITION", "Cannot add todo to a deleted_remote database")

    # create "Notion" page id locally
    notion_page_id = _gen_id("nia_npg_")  # internal synthetic but stable-form string
    page_id = _gen_id("nia_pag_")
    todo_id = _gen_id("nia_tod_")

    # enforce unique(todos.integration_id, todos.notion_page_id) and unique(pages.integration_id, pages.notion_page_id)
    if any(isinstance(p, dict) and p.get("integration_id") == integration_id and p.get("notion_page_id") == notion_page_id for p in pages):
        notion_page_id = _gen_id("nia_npg_")
    if any(isinstance(t, dict) and t.get("integration_id") == integration_id and t.get("notion_page_id") == notion_page_id for t in todos):
        notion_page_id = _gen_id("nia_npg_")

    # minimal Notion-like properties payload
    props = {
        "Title": {"id": "title", "type": "title", "title": [{"type": "text", "plain_text": title}]},
    }
    if description is not None:
        props["Description"] = {"id": "description", "type": "rich_text", "rich_text": [{"type": "text", "plain_text": str(description)}]}
    if due_iso is not None:
        props["Due"] = {"id": "due", "type": "date", "date": {"start": due_iso, "end": None, "time_zone": "UTC"}}
    if priority is not None:
        props["Priority"] = {"id": "priority", "type": "select", "select": {"name": priority}}
    if tags is not None:
        props["Tags"] = {"id": "tags", "type": "multi_select", "multi_select": [{"name": x} for x in tags]}
    if assignees is not None:
        props["Assignees"] = {"id": "assignees", "type": "people", "people": [{"id": x} for x in assignees]}

    # insert page mirror row
    page_row = {
        "id": page_id,
        "integration_id": integration_id,
        "notion_page_id": notion_page_id,
        "parent_type": "database",
        "parent_notion_id": db.get("notion_database_id"),
        "in_database_notion_id": db.get("notion_database_id"),
        "title_plaintext": title,
        "icon": None,
        "cover": None,
        "properties": props,
        "archived": False,
        "status": "active",
        "notion_created_time": now,
        "notion_last_edited_time": now,
        "last_synced_at": now,
        "last_sync_error": None,
        "created_at": now,
        "updated_at": now,
    }
    pages.append(page_row)

    # insert todo row
    todo_row = {
        "id": todo_id,
        "integration_id": integration_id,
        "database_id": database_id,
        "page_id": page_id,
        "notion_page_id": notion_page_id,
        "title": title,
        "description": description if (isinstance(description, str) or description is None) else str(description),
        "due_at": due_iso,
        "priority": priority,
        "tags": tags if tags is not None else None,
        "assignees": assignees if assignees is not None else None,
        "completed": False,
        "completed_at": None,
        "archived": False,
        "status": "open",
        "created_at": now,
        "updated_at": now,
    }
    todos.append(todo_row)

    # persist
    _save("pages.json", pages)
    _save("todos.json", todos)

    _log(True, integration_id, notion_endpoint="/v1/pages", notion_http_status=200,
         request_payload={"integration_id": integration_id, "database_id": database_id, "title": title})

    return {"todo": todo_row, "page": page_row}

def search_todos(integration_id, database_id=None, query=None, filter=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "INVALID"
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return "INVALID"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = os.urandom(16)
        num = int.from_bytes(raw, "big")
        s = ""
        for _ in range(20):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return f"{prefix}_{s.lstrip('0') or '0'*17}"

    def _log(integration_id_val, success, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        logs = _load("request_logs.json")
        now = _now()
        rid = _gen_id("nia_rql")
        duration_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": rid,
            "integration_id": integration_id_val,
            "tool_name": "search_todos",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, duration_ms),
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("request_logs.json", logs)
        return row

    def _payload():
        return {
            "integration_id": integration_id,
            "database_id": database_id,
            "query": query,
            "filter": filter,
            "sort": sort,
            "limit": limit,
            "cursor": cursor,
        }

    # Validate
    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(integration_id if isinstance(integration_id, str) else "unknown", False, error_code="validation_error", error_message="Invalid integration_id", request_payload=_payload())
        return _err("VALIDATION_ERROR", "integration_id is missing or invalid")
    if database_id is not None and (not isinstance(database_id, str) or not re.match(r"^nia_dbs_[0-9A-HJKMNP-TV-Z]{17,}$", database_id)):
        _log(integration_id, False, error_code="validation_error", error_message="Invalid database_id", request_payload=_payload())
        return _err("VALIDATION_ERROR", "database_id is invalid")
    if query is not None and not isinstance(query, str):
        _log(integration_id, False, error_code="validation_error", error_message="Invalid query", request_payload=_payload())
        return _err("VALIDATION_ERROR", "query must be a string when provided")
    if limit is not None and (not isinstance(limit, int) or limit < 1 or limit > 100):
        _log(integration_id, False, error_code="validation_error", error_message="limit out of range", request_payload=_payload())
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        _log(integration_id, False, error_code="validation_error", error_message="Invalid cursor", request_payload=_payload())
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    if filter is not None:
        if not isinstance(filter, dict):
            _log(integration_id, False, error_code="validation_error", error_message="filter must be object", request_payload=_payload())
            return _err("VALIDATION_ERROR", "filter must be an object")
        allowed_keys = {"status", "completed", "priority", "archived", "due_before", "due_after", "tags", "assignees"}
        for k in filter.keys():
            if k not in allowed_keys:
                _log(integration_id, False, error_code="validation_error", error_message=f"Unsupported filter field {k}", request_payload=_payload())
                return _err("VALIDATION_ERROR", f"Unsupported filter field: {k}")
        if "status" in filter and filter["status"] not in ("open", "completed", "archived"):
            _log(integration_id, False, error_code="validation_error", error_message="Invalid status filter", request_payload=_payload())
            return _err("VALIDATION_ERROR", "filter.status invalid")
        if "completed" in filter and not isinstance(filter["completed"], bool):
            _log(integration_id, False, error_code="validation_error", error_message="Invalid completed filter", request_payload=_payload())
            return _err("VALIDATION_ERROR", "filter.completed must be boolean")
        if "priority" in filter and filter["priority"] is not None and filter["priority"] not in ("low", "medium", "high", "urgent"):
            _log(integration_id, False, error_code="validation_error", error_message="Invalid priority filter", request_payload=_payload())
            return _err("VALIDATION_ERROR", "filter.priority invalid")
        if "archived" in filter and not isinstance(filter["archived"], bool):
            _log(integration_id, False, error_code="validation_error", error_message="Invalid archived filter", request_payload=_payload())
            return _err("VALIDATION_ERROR", "filter.archived must be boolean")
        for dtf in ("due_before", "due_after"):
            if dtf in filter:
                parsed = _parse_dt(filter[dtf])
                if parsed == "INVALID":
                    _log(integration_id, False, error_code="validation_error", error_message=f"Invalid {dtf}", request_payload=_payload())
                    return _err("VALIDATION_ERROR", f"filter.{dtf} must be ISO-8601 date-time")
        if "tags" in filter:
            v = filter["tags"]
            if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
                _log(integration_id, False, error_code="validation_error", error_message="Invalid tags filter", request_payload=_payload())
                return _err("VALIDATION_ERROR", "filter.tags must be an array of strings")
        if "assignees" in filter:
            v = filter["assignees"]
            if not isinstance(v, list) or any(not isinstance(x, str) for x in v):
                _log(integration_id, False, error_code="validation_error", error_message="Invalid assignees filter", request_payload=_payload())
                return _err("VALIDATION_ERROR", "filter.assignees must be an array of strings")

    if sort is not None:
        if not isinstance(sort, list):
            _log(integration_id, False, error_code="validation_error", error_message="sort must be array", request_payload=_payload())
            return _err("VALIDATION_ERROR", "sort must be an array")
        allowed_fields = {"created_at", "updated_at", "due_at", "priority", "title", "completed_at"}
        for s in sort:
            if not isinstance(s, dict) or set(s.keys()) != {"field", "direction"}:
                _log(integration_id, False, error_code="validation_error", error_message="Invalid sort item", request_payload=_payload())
                return _err("VALIDATION_ERROR", "Each sort item must be {field, direction}")
            if s["field"] not in allowed_fields:
                _log(integration_id, False, error_code="validation_error", error_message="Unsupported sort field", request_payload=_payload())
                return _err("VALIDATION_ERROR", f"Unsupported sort field: {s['field']}")
            if s["direction"] not in ("asc", "desc"):
                _log(integration_id, False, error_code="validation_error", error_message="Unsupported sort direction", request_payload=_payload())
                return _err("VALIDATION_ERROR", f"Unsupported sort direction: {s['direction']}")

    integrations = _load("integrations.json")
    integ = next((x for x in integrations if x.get("id") == integration_id), None)
    if not integ:
        _log(integration_id, False, error_code="unauthorized", error_message="Unknown integration", request_payload=_payload())
        return _err("UNAUTHORIZED", "integration_id is unknown")

    # If database_id specified, ensure it exists for this integration
    if database_id is not None:
        databases = _load("databases.json")
        if not any(d.get("id") == database_id and d.get("integration_id") == integration_id for d in databases):
            _log(integration_id, False, error_code="not_found", error_message="Database not found", request_payload=_payload())
            return _err("NOT_FOUND", "database_id not found for this integration")

    todos = _load("todos.json")
    pages = _load("pages.json")
    page_by_id = {p.get("id"): p for p in pages if p.get("integration_id") == integration_id}

    # Apply filters
    items = [t for t in todos if t.get("integration_id") == integration_id]
    if database_id is not None:
        items = [t for t in items if t.get("database_id") == database_id]

    q = (query or "").strip().lower() if query is not None else None
    if q:
        def _text(t):
            return ((t.get("title") or "") + " " + (t.get("description") or "")).lower()
        items = [t for t in items if q in _text(t)]

    f = filter or {}
    if "status" in f:
        items = [t for t in items if t.get("status") == f["status"]]
    if "completed" in f:
        items = [t for t in items if bool(t.get("completed")) == f["completed"]]
    if "priority" in f:
        items = [t for t in items if t.get("priority") == f["priority"]]
    if "archived" in f:
        items = [t for t in items if bool(t.get("archived")) == f["archived"]]

    due_before = _parse_dt(f.get("due_before")) if "due_before" in f else None
    due_after = _parse_dt(f.get("due_after")) if "due_after" in f else None

    def _todo_due_dt(t):
        s = t.get("due_at")
        if not isinstance(s, str):
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if isinstance(due_before, datetime.datetime):
        items = [t for t in items if (_todo_due_dt(t) is not None and _todo_due_dt(t) < due_before)]
    if isinstance(due_after, datetime.datetime):
        items = [t for t in items if (_todo_due_dt(t) is not None and _todo_due_dt(t) > due_after)]

    if "tags" in f:
        want = set([x.lower() for x in (f.get("tags") or [])])
        def _tags(t):
            v = t.get("tags")
            if not isinstance(v, list):
                return set()
            return set([str(x).lower() for x in v])
        # backend-defined matching: "contains all"
        items = [t for t in items if want.issubset(_tags(t))]

    if "assignees" in f:
        want = set(f.get("assignees") or [])
        def _assignees(t):
            v = t.get("assignees")
            if not isinstance(v, list):
                return set()
            return set([str(x) for x in v])
        items = [t for t in items if want.issubset(_assignees(t))]

    # Sorting
    def _key_for(field, t):
        v = t.get(field)
        if field in ("created_at", "updated_at", "due_at", "completed_at"):
            if not isinstance(v, str):
                return (1, None)
            try:
                dt = datetime.datetime.fromisoformat(v.replace("Z", "+00:00")).astimezone(datetime.timezone.utc)
                return (0, dt)
            except Exception:
                return (1, None)
        if field == "priority":
            order = {"low": 1, "medium": 2, "high": 3, "urgent": 4, None: 99}
            return (0, order.get(v, 98))
        if field == "title":
            return (0, (v or "").lower())
        return (0, v)

    if sort:
        # apply stable sorts from last to first
        for s in reversed(sort):
            field = s["field"]
            direction = s["direction"]
            items.sort(key=lambda t, f=field: _key_for(f, t), reverse=(direction == "desc"))
    else:
        # default: updated_at desc
        items.sort(key=lambda t: _key_for("updated_at", t), reverse=True)

    total = len(items)

    # Pagination cursor as offset
    offset = 0
    if cursor is not None:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8", "strict")
            if decoded.startswith("off:"):
                offset = int(decoded.split(":", 1)[1])
                if offset < 0:
                    raise ValueError()
        except Exception:
            _log(integration_id, False, error_code="validation_error", error_message="Invalid cursor", request_payload=_payload())
            return _err("VALIDATION_ERROR", "cursor is invalid")

    lim = limit if limit is not None else 50
    page_items = items[offset:offset + lim]
    next_off = offset + lim
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Attach page linkage info (required mapping)
    results = []
    for t in page_items:
        p = page_by_id.get(t.get("page_id"))
        results.append({
            "todo": t,
            "page": p,
            "notion_page_id": (p.get("notion_page_id") if isinstance(p, dict) else t.get("notion_page_id")),
        })

    _log(integration_id, True, notion_endpoint=None, notion_http_status=None, request_payload=_payload())
    return {
        "todos": results,
        "total": total,
        "limit": lim,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "cursor": cursor,
    }

def query_database(integration_id, database_id, filter=None, sorts=None, page_size=None, start_cursor=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        num = int.from_bytes(b, "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "query_database",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", logs)

    # validate (accept {17,} to match datastore ids)
    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, integration_id if isinstance(integration_id, str) else "", error_code="validation_error",
             error_message="integration_id is missing or malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id})
        return _err("VALIDATION_ERROR", "integration_id is missing or malformed")
    if not isinstance(database_id, str) or not re.match(r"^nia_dbs_[0-9A-HJKMNP-TV-Z]{17,}$", database_id):
        _log(False, integration_id, error_code="validation_error", error_message="database_id is missing or malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id})
        return _err("VALIDATION_ERROR", "database_id is missing or malformed")
    if filter is not None and not isinstance(filter, dict):
        _log(False, integration_id, error_code="validation_error", error_message="filter must be an object",
             request_payload={"integration_id": integration_id, "database_id": database_id})
        return _err("VALIDATION_ERROR", "filter must be an object")
    if sorts is not None and (not isinstance(sorts, list) or any(not isinstance(x, dict) for x in sorts)):
        _log(False, integration_id, error_code="validation_error", error_message="sorts must be an array of objects",
             request_payload={"integration_id": integration_id, "database_id": database_id})
        return _err("VALIDATION_ERROR", "sorts must be an array of objects")
    if page_size is not None:
        if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
            _log(False, integration_id, error_code="validation_error",
                 error_message="page_size must be an integer between 1 and 100",
                 request_payload={"integration_id": integration_id, "database_id": database_id, "page_size": page_size})
            return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")
    else:
        page_size = 100

    integrations = _load("integrations.json")
    if isinstance(integrations, dict) and "rows" in integrations:
        integrations = []
    if not isinstance(integrations, list):
        integrations = []

    databases = _load("databases.json")
    if isinstance(databases, dict) and "rows" in databases:
        databases = []
    if not isinstance(databases, list):
        databases = []

    pages = _load("pages.json")
    if isinstance(pages, dict) and "rows" in pages:
        pages = []
    if not isinstance(pages, list):
        pages = []

    integ = next((r for r in integrations if isinstance(r, dict) and r.get("id") == integration_id), None)
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id",
             request_payload={"integration_id": integration_id, "database_id": database_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    db = next((r for r in databases if isinstance(r, dict) and r.get("id") == database_id and r.get("integration_id") == integration_id), None)
    if not db:
        _log(False, integration_id, notion_endpoint="/v1/databases/{id}/query", notion_http_status=404,
             error_code="object_not_found", error_message="Database not found",
             request_payload={"integration_id": integration_id, "database_id": database_id, "filter": filter, "sorts": sorts, "page_size": page_size, "start_cursor": start_cursor})
        return _err("NOT_FOUND", "Database not found")

    notion_db_id = db.get("notion_database_id")
    # local cache query: pages where in_database_notion_id matches db notion id
    candidates = []
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("integration_id") != integration_id:
            continue
        if p.get("in_database_notion_id") != notion_db_id:
            continue
        # only return not deleted_remote by default
        if p.get("status") == "deleted_remote":
            continue
        candidates.append(p)

    # naive deterministic sort if sorts contains something like {"timestamp":"last_edited_time","direction":"descending"}.
    # If not provided or malformed, keep stable order by created_at.
    def _get_dt(x):
        v = x.get("notion_last_edited_time") or x.get("notion_created_time") or x.get("created_at") or ""
        return v if isinstance(v, str) else ""
    reverse = False
    if isinstance(sorts, list) and sorts:
        s0 = sorts[0]
        if isinstance(s0, dict) and str(s0.get("direction", "")).lower() == "descending":
            reverse = True
    candidates.sort(key=_get_dt, reverse=reverse)

    # cursor pagination: accept integer offset encoded as string; otherwise treat as 0
    start = 0
    if start_cursor is not None:
        try:
            start = int(start_cursor)
            if start < 0:
                start = 0
        except Exception:
            start = 0

    sliced = candidates[start:start + page_size]
    has_more = (start + page_size) < len(candidates)
    next_cursor = str(start + page_size) if has_more else None

    # update db sync timestamp (query hits Notion in real life)
    db["last_synced_at"] = now
    db["updated_at"] = now
    _save("databases.json", databases)

    _log(True, integration_id, notion_endpoint=f"/v1/databases/{notion_db_id}/query", notion_http_status=200,
         request_payload={"integration_id": integration_id, "database_id": database_id, "filter": filter, "sorts": sorts, "page_size": page_size, "start_cursor": start_cursor})

    return {
        "object": "list",
        "results": sliced,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "total": len(candidates),
        "database": {"id": db.get("id"), "notion_database_id": notion_db_id},
    }

def verify_connection(integration_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    integrations = _load("integrations.json")
    reqlogs = _load("request_logs.json")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        num = int.from_bytes(b, "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    def _parse_iso(s):
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        reqlogs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "verify_connection",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", reqlogs)

    def _rate_limited(integration_id_val):
        if not isinstance(integration_id_val, str) or not integration_id_val:
            return False
        cutoff = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqlogs:
            if not isinstance(r, dict) or r.get("integration_id") != integration_id_val:
                continue
            dt = _parse_iso(r.get("created_at", ""))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt >= 3

    payload = {"integration_id": integration_id}

    # IMPORTANT: tool schema pattern was too strict in broken code; accept real ids in store (17+)
    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, integration_id if isinstance(integration_id, str) else "", notion_endpoint="/v1/users/me",
             error_code="validation_error", error_message="integration_id is invalid", request_payload=payload)
        return _err("VALIDATION_ERROR", "integration_id is invalid")

    integ = None
    for r in integrations:
        if isinstance(r, dict) and r.get("id") == integration_id:
            integ = r
            break
    if not integ:
        _log(False, integration_id, notion_endpoint="/v1/users/me", notion_http_status=404,
             error_code="not_found", error_message="Integration record does not exist", request_payload=payload)
        return _err("NOT_FOUND", "Integration record does not exist")

    if _rate_limited(integration_id):
        _log(False, integration_id, notion_endpoint="/v1/users/me", notion_http_status=429,
             error_code="rate_limited", error_message="Notion rate limit hit; please retry", request_payload=payload)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Verify prerequisites: token fields must exist and base_url/version not empty
    if not isinstance(integ.get("encrypted_access_token"), str) or not integ.get("encrypted_access_token"):
        integ["last_error_code"] = "missing_credentials"
        integ["last_error_message"] = "Stored Notion credentials are missing"
        integ["updated_at"] = now
        _save("integrations.json", integrations)
        _log(False, integration_id, notion_endpoint="/v1/users/me", notion_http_status=401,
             error_code="missing_credentials", error_message="Stored Notion credentials are missing", request_payload=payload)
        return _err("UNAUTHORIZED", "Stored Notion credentials are missing")

    if not isinstance(integ.get("notion_api_base_url"), str) or integ.get("notion_api_base_url") == "" or not isinstance(integ.get("notion_api_version"), str) or integ.get("notion_api_version") == "":
        integ["last_error_code"] = "invalid_configuration"
        integ["last_error_message"] = "Integration Notion API configuration is incomplete"
        integ["updated_at"] = now
        _save("integrations.json", integrations)
        _log(False, integration_id, notion_endpoint="/v1/users/me", notion_http_status=400,
             error_code="invalid_configuration", error_message="Integration Notion API configuration is incomplete", request_payload=payload)
        return _err("VALIDATION_ERROR", "Integration Notion API configuration is incomplete")

    # Offline "Notion call" simulation based on stored status/error (do not require plaintext token).
    # If currently revoked, treat as auth failure. Otherwise succeed.
    if integ.get("status") == "revoked" or integ.get("last_error_code") == "invalid_auth":
        # transition to revoked (idempotent) and set last_error*
        integ["status"] = "revoked"
        integ["last_error_code"] = "invalid_auth"
        integ["last_error_message"] = integ.get("last_error_message") or "Invalid API token. The integration secret appears to be revoked."
        integ["updated_at"] = now
        _save("integrations.json", integrations)
        _log(False, integration_id, notion_endpoint="/v1/users/me", notion_http_status=401,
             error_code="invalid_auth", error_message=integ.get("last_error_message"), request_payload=payload)
        return _err("UNAUTHORIZED", "Notion authentication failed", notion_error_code="invalid_auth")

    # Success: set last_verified_at and transition to active if allowed
    transitions = {
        "active": {"degraded", "disabled", "revoked"},
        "degraded": {"active", "disabled", "revoked"},
        "disabled": {"active", "revoked"},
        "revoked": set(),
    }
    cur = integ.get("status") if isinstance(integ.get("status"), str) else "degraded"
    if cur not in transitions:
        cur = "degraded"
    if cur != "active":
        if "active" not in transitions.get(cur, set()):
            _log(False, integration_id, notion_endpoint="/v1/users/me", notion_http_status=409,
                 error_code="invalid_transition", error_message=f"Illegal integration status transition {cur} -> active",
                 request_payload=payload)
            return _err("INVALID_TRANSITION", f"Illegal integration status transition {cur} -> active")
        integ["status"] = "active"

    integ["last_verified_at"] = now
    integ["last_error_code"] = None
    integ["last_error_message"] = None
    integ["updated_at"] = now
    _save("integrations.json", integrations)

    _log(True, integration_id, notion_endpoint="/v1/users/me", notion_http_status=200, request_payload=payload)
    return {
        "object": "integration_verification",
        "integration": integ,
        "verified": True
    }

def get_database_info(integration_id, database_id=None, notion_database_id=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        num = int.from_bytes(b, "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        logs = _load("request_logs.json")
        logs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "get_database_info",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", logs)

    if not isinstance(integration_id, str) or not re.match(r"^nia_int_[0-9A-HJKMNP-TV-Z]{17,}$", integration_id):
        _log(False, integration_id if isinstance(integration_id, str) else "", error_code="validation_error",
             error_message="integration_id is missing or malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})
        return _err("VALIDATION_ERROR", "integration_id is missing or malformed")

    if database_id is None and notion_database_id is None:
        _log(False, integration_id, error_code="validation_error",
             error_message="Either database_id or notion_database_id must be provided",
             request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})
        return _err("VALIDATION_ERROR", "Either database_id or notion_database_id must be provided")

    if database_id is not None and (not isinstance(database_id, str) or not re.match(r"^nia_dbs_[0-9A-HJKMNP-TV-Z]{17,}$", database_id)):
        _log(False, integration_id, error_code="validation_error", error_message="database_id is malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})
        return _err("VALIDATION_ERROR", "database_id is malformed")

    if notion_database_id is not None and (not isinstance(notion_database_id, str) or not notion_database_id.strip()):
        _log(False, integration_id, error_code="validation_error", error_message="notion_database_id is malformed",
             request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})
        return _err("VALIDATION_ERROR", "notion_database_id is malformed")

    integrations = _load("integrations.json")
    if isinstance(integrations, dict) and "rows" in integrations:
        integrations = []
    if not isinstance(integrations, list):
        integrations = []

    databases = _load("databases.json")
    if isinstance(databases, dict) and "rows" in databases:
        databases = []
    if not isinstance(databases, list):
        databases = []

    integ = next((r for r in integrations if isinstance(r, dict) and r.get("id") == integration_id), None)
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id",
             request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    db = None
    if database_id is not None:
        db = next((r for r in databases if isinstance(r, dict) and r.get("id") == database_id and r.get("integration_id") == integration_id), None)
    if db is None and notion_database_id is not None:
        db = next((r for r in databases if isinstance(r, dict) and r.get("notion_database_id") == notion_database_id and r.get("integration_id") == integration_id), None)

    if db is None:
        _log(False, integration_id, notion_endpoint="/v1/databases/{id}", notion_http_status=404,
             error_code="object_not_found", error_message="Database not found in mirror",
             request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})
        return _err("NOT_FOUND", "Database not found")

    # keep sync timestamp fresh on read
    db["last_synced_at"] = now
    db["updated_at"] = now
    _save("databases.json", databases)

    _log(True, integration_id, notion_endpoint=f"/v1/databases/{db.get('notion_database_id')}", notion_http_status=200,
         request_payload={"integration_id": integration_id, "database_id": database_id, "notion_database_id": notion_database_id})

    return {"database": db}

def add_content_blocks(integration_id, blocks, parent_block_id=None, parent_notion_block_id=None, after_block_notion_id=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0066000" if __import__("os").path.isdir("./environment_mix/0066000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        num = int.from_bytes(os.urandom(16), "big")
        s = ""
        for _ in range(17):
            num, r = divmod(num, 32)
            s = alphabet[r] + s
        return prefix + s

    integrations = _load("integrations.json")
    pages = _load("pages.json")
    blocks_store = _load("blocks.json")
    reqlogs = _load("request_logs.json")

    def _rate_limited(integration_id_val):
        cutoff = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for r in reqlogs:
            if not isinstance(r, dict):
                continue
            if r.get("integration_id") != integration_id_val:
                continue
            dt = _parse_iso(r.get("created_at"))
            if dt and dt >= cutoff:
                cnt += 1
        return cnt >= 60

    def _log(success, integration_id_val, notion_endpoint=None, notion_http_status=None, error_code=None, error_message=None, request_payload=None):
        reqlogs.append({
            "id": _gen_id("nia_req_"),
            "integration_id": integration_id_val if isinstance(integration_id_val, str) else "",
            "tool_name": "add_content_blocks",
            "request_payload": request_payload,
            "notion_endpoint": notion_endpoint,
            "notion_http_status": notion_http_status,
            "success": bool(success),
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": max(0, int((time.time() - t0) * 1000)),
            "created_at": now,
            "updated_at": now,
        })
        _save("request_logs.json", reqlogs)

    # Validate
    if not isinstance(integration_id, str) or not integration_id:
        _log(False, integration_id, error_code="validation_error", error_message="integration_id must be a non-empty string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "integration_id must be a non-empty string")
    if not isinstance(blocks, list) or len(blocks) < 1:
        _log(False, integration_id, error_code="validation_error", error_message="blocks must be a non-empty array", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "blocks must be a non-empty array")
    for i, b in enumerate(blocks):
        if not isinstance(b, dict):
            _log(False, integration_id, error_code="validation_error", error_message=f"blocks[{i}] must be an object", request_payload={"integration_id": integration_id})
            return _err("VALIDATION_ERROR", f"blocks[{i}] must be an object")
    if parent_block_id is None and parent_notion_block_id is None:
        _log(False, integration_id, error_code="validation_error", error_message="parent_block_id or parent_notion_block_id is required", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "parent_block_id or parent_notion_block_id is required")
    if parent_block_id is not None and not isinstance(parent_block_id, str):
        _log(False, integration_id, error_code="validation_error", error_message="parent_block_id must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "parent_block_id must be a string")
    if parent_notion_block_id is not None and not isinstance(parent_notion_block_id, str):
        _log(False, integration_id, error_code="validation_error", error_message="parent_notion_block_id must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "parent_notion_block_id must be a string")
    if after_block_notion_id is not None and not isinstance(after_block_notion_id, str):
        _log(False, integration_id, error_code="validation_error", error_message="after_block_notion_id must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "after_block_notion_id must be a string")

    integ = None
    for r in integrations:
        if isinstance(r, dict) and r.get("id") == integration_id:
            integ = r
            break
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id", request_payload={"integration_id": integration_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")
    if integ.get("status") in ("disabled", "revoked"):
        _log(False, integration_id, error_code="unauthorized", error_message="Integration is disabled or revoked; mutating tools are not allowed", request_payload={"integration_id": integration_id})
        return _err("UNAUTHORIZED", "Integration is disabled or revoked; mutating tools are not allowed")

    if _rate_limited(integration_id):
        _log(False, integration_id, notion_endpoint="/v1/blocks/{id}/children", notion_http_status=429, error_code="rate_limited", error_message="Notion rate limit backoff", request_payload={"integration_id": integration_id})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Resolve parent block
    parent_local = None
    if parent_block_id:
        for b in blocks_store:
            if isinstance(b, dict) and b.get("id") == parent_block_id and b.get("integration_id") == integration_id:
                parent_local = b
                break
        # If the caller provided a parent_block_id that exists, accept even if parent_notion_block_id points elsewhere
        if not parent_local:
            _log(False, integration_id, error_code="not_found", error_message="parent_block_id not found for integration", request_payload={"integration_id": integration_id, "parent_block_id": parent_block_id})
            return _err("NOT_FOUND", "Parent block not found")
        parent_notion = parent_local.get("notion_block_id") or parent_notion_block_id
    else:
        parent_notion = parent_notion_block_id

    if not isinstance(parent_notion, str) or not parent_notion:
        _log(False, integration_id, error_code="validation_error", error_message="Could not resolve parent Notion block id", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "Could not resolve parent Notion block id")

    # Determine insertion index among existing children (by position_index)
    siblings = [b for b in blocks_store if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("parent_notion_block_id") == parent_notion]
    siblings_sorted = sorted(siblings, key=lambda x: (x.get("position_index") if isinstance(x.get("position_index"), int) else 10**9, x.get("created_at") or ""))
    insert_at = len(siblings_sorted)

    if after_block_notion_id:
        # IMPORTANT: Do not enforce strict Notion-id shape; accept any string.
        # Find sibling by notion_block_id.
        idx = None
        for i, s in enumerate(siblings_sorted):
            if s.get("notion_block_id") == after_block_notion_id:
                idx = i
                break
        if idx is not None:
            insert_at = idx + 1
        else:
            # If after_block_notion_id not found, behave like Notion: append.
            insert_at = len(siblings_sorted)

    # Shift position_index of following siblings to make room
    for s in siblings_sorted[insert_at:]:
        if isinstance(s.get("position_index"), int) and s.get("position_index") >= insert_at:
            s["position_index"] = s.get("position_index") + len(blocks)
            s["updated_at"] = now
        elif s.get("position_index") is None:
            # if existing are null, leave them null; we'll set indices for new blocks only
            pass

    created = []
    # Create new block mirror rows (simulate successful Notion creation)
    for i, payload in enumerate(blocks):
        # determine type
        bt = payload.get("type") if isinstance(payload, dict) else None
        allowed_types = {
            "paragraph", "heading_1", "heading_2", "heading_3", "bulleted_list_item", "numbered_list_item",
            "to_do", "toggle", "quote", "code", "callout", "divider", "image", "video", "file", "bookmark",
            "embed", "equation", "table", "table_row", "child_page", "child_database", "synced_block",
            "column_list", "column", "link_to_page", "breadcrumb", "table_of_contents", "unsupported", "unknown"
        }
        if bt is None:
            bt = "unknown"
        if bt not in allowed_types:
            _log(False, integration_id, error_code="validation_error", error_message=f"Unsupported block type: {bt}", request_payload={"integration_id": integration_id})
            return _err("VALIDATION_ERROR", f"Unsupported block type: {bt}")

        # generate a notion-like id (uuid string) for local simulation if missing
        notion_id = payload.get("id")
        if not isinstance(notion_id, str) or not notion_id:
            # uuid4-like
            import uuid
            notion_id = str(uuid.uuid4())

        # enforce unique(integration_id, notion_block_id) idempotency
        exists = None
        for b in blocks_store:
            if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("notion_block_id") == notion_id:
                exists = b
                break
        if exists:
            # idempotent: ensure linkage is correct; do not create duplicate
            exists["parent_notion_block_id"] = parent_notion
            if parent_local:
                exists["parent_block_id"] = parent_local.get("id")
                exists["root_page_id"] = parent_local.get("root_page_id")
            exists["block_type"] = exists.get("block_type") or bt
            exists["content"] = exists.get("content") if isinstance(exists.get("content"), dict) else payload
            exists["updated_at"] = now
            created.append(exists)
            continue

        row = {
            "id": _gen_id("nia_blk_"),
            "integration_id": integration_id,
            "notion_block_id": notion_id,
            "root_page_id": parent_local.get("root_page_id") if parent_local else None,
            "parent_block_id": parent_local.get("id") if parent_local else None,
            "parent_notion_block_id": parent_notion,
            "block_type": bt,
            "has_children": bool(payload.get("has_children")) if isinstance(payload.get("has_children"), bool) else False,
            "position_index": insert_at + i,
            "content": payload,
            "archived": False,
            "status": "active",
            "notion_created_time": now,
            "notion_last_edited_time": now,
            "last_synced_at": now,
            "last_sync_error": None,
            "created_at": now,
            "updated_at": now,
        }

        # Constraint: parent_block_id is null OR root_page_id is not null
        if row["parent_block_id"] is not None and row["root_page_id"] is None:
            # If we can't resolve root_page_id from parent block, attempt from a known page that contains the parent notion block
            # best-effort: find any block with that parent notion id and reuse its root_page_id
            for b in blocks_store:
                if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("notion_block_id") == parent_notion:
                    row["root_page_id"] = b.get("root_page_id")
                    break
            if row["root_page_id"] is None:
                # still cannot satisfy constraint; degrade gracefully by dropping parent_block_id linkage
                row["parent_block_id"] = None

        blocks_store.append(row)
        created.append(row)

    _save("blocks.json", blocks_store)
    _log(True, integration_id, notion_endpoint=f"/v1/blocks/{parent_notion}/children", notion_http_status=200, request_payload={"integration_id": integration_id, "parent_block_id": parent_block_id, "parent_notion_block_id": parent_notion_block_id, "after_block_notion_id": after_block_notion_id})
    return {"object": "list", "results": created, "count": len(created)}

