        return _err("VALIDATION_ERROR", "notion_block_id must be a string")
    if page_size is None:
        page_size = 100
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        _log(False, integration_id, error_code="validation_error", error_message="page_size must be between 1 and 100", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 100")
    if start_cursor is not None and not isinstance(start_cursor, str):
        _log(False, integration_id, error_code="validation_error", error_message="start_cursor must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "start_cursor must be a string")

    integ = None
    for r in integrations:
        if isinstance(r, dict) and r.get("id") == integration_id:
            integ = r
            break
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id", request_payload={"integration_id": integration_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")

    if _rate_limited(integration_id):
        _log(False, integration_id, notion_endpoint="/v1/blocks/{id}/children", notion_http_status=429, error_code="rate_limited", error_message="Notion rate limit backoff", request_payload={"integration_id": integration_id})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # resolve parent notion id
    parent_notion = None
    if notion_block_id:
        parent_notion = notion_block_id
    else:
        parent_local = None
        for b in blocks_store:
            if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("id") == block_id:
                parent_local = b
                break
        if not parent_local:
            _log(False, integration_id, notion_endpoint=f"/v1/blocks/{block_id}/children", notion_http_status=404, error_code="not_found", error_message="Parent block not found", request_payload={"integration_id": integration_id, "block_id": block_id})
            return _err("NOT_FOUND", "Parent block not found")
        parent_notion = parent_local.get("notion_block_id")

    if not isinstance(parent_notion, str) or not parent_notion:
        _log(False, integration_id, error_code="validation_error", error_message="Could not resolve parent Notion block id", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "Could not resolve parent Notion block id")

    children = [b for b in blocks_store if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("parent_notion_block_id") == parent_notion]
    children_sorted = sorted(children, key=lambda x: (x.get("position_index") if isinstance(x.get("position_index"), int) else 10**9, x.get("created_at") or ""))

    # paginate using idx:<n> token
    offset = 0
    if start_cursor:
        if start_cursor.startswith("idx:"):
            try:
                offset = int(start_cursor.split(":", 1)[1])
            except Exception:
                offset = 0
        else:
            offset = 0
    if offset < 0:
        offset = 0

    page_items = children_sorted[offset: offset + page_size]
    has_more = offset + page_size < len(children_sorted)
    next_cursor = f"idx:{offset + page_size}" if has_more else None

    _log(True, integration_id, notion_endpoint=f"/v1/blocks/{parent_notion}/children", notion_http_status=200, request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id, "page_size": page_size, "start_cursor": start_cursor})
    return {"object": "list", "results": page_items, "has_more": has_more, "next_cursor": next_cursor}

