    # Validate
    if not isinstance(integration_id, str) or not integration_id:
        _log(False, integration_id, error_code="validation_error", error_message="integration_id must be a non-empty string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "integration_id must be a non-empty string")
    if block_id is None and notion_block_id is None:
        _log(False, integration_id, error_code="validation_error", error_message="block_id or notion_block_id is required", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "block_id or notion_block_id is required")
    if block_id is not None and not isinstance(block_id, str):
        _log(False, integration_id, error_code="validation_error", error_message="block_id must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "block_id must be a string")
