        _log(False, integration_id, error_code="validation_error", error_message="notion_block_id must be a string", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "notion_block_id must be a string")
    allowed_types = {
        "paragraph", "heading_1", "heading_2", "heading_3", "bulleted_list_item", "numbered_list_item", "to_do",
        "toggle", "quote", "code", "callout", "divider", "image", "video", "file", "bookmark", "embed", "equation",
        "table", "table_row", "child_page", "child_database", "synced_block", "column_list", "column",
        "link_to_page", "breadcrumb", "table_of_contents", "unsupported", "unknown"
    }
    if block_type is not None and (not isinstance(block_type, str) or block_type not in allowed_types):
        _log(False, integration_id, error_code="validation_error", error_message="block_type is invalid/unsupported", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "block_type is invalid/unsupported")
