        _log(False, integration_id, error_code="validation_error", error_message="content must be an object", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "content must be an object")
    if archived is not None and not isinstance(archived, bool):
        _log(False, integration_id, error_code="validation_error", error_message="archived must be a boolean", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "archived must be a boolean")
    if content is None and archived is None and block_type is None:
        _log(False, integration_id, error_code="validation_error", error_message="No updates provided", request_payload={"integration_id": integration_id})
        return _err("VALIDATION_ERROR", "No updates provided")

    integ = None
    for r in integrations:
        if isinstance(r, dict) and r.get("id") == integration_id:
            integ = r
            break
    if not integ:
        _log(False, integration_id, error_code="unauthorized", error_message="Unknown integration_id", request_payload={"integration_id": integration_id})
        return _err("UNAUTHORIZED", "Unknown integration_id")
    if integ.get("status") in ("disabled", "revoked"):
        _log(False, integration_id, error_code="unauthorized", error_message="Integration is disabled or revoked; mutating tools are not allowed", request_payload={"integration_id": integration_id})
        return _err("UNAUTHORIZED", "Integration is disabled or revoked; mutating tools are not allowed")

    if _rate_limited(integration_id):
        _log(False, integration_id, notion_endpoint="/v1/blocks/{id}", notion_http_status=429, error_code="rate_limited", error_message="Notion rate limit backoff", request_payload={"integration_id": integration_id})
        return _err("RATE_LIMIT", "Rate limit exceeded")

    blk = None
    if block_id:
        for b in blocks_store:
            if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("id") == block_id:
                blk = b
                break
    if not blk and notion_block_id:
        for b in blocks_store:
            if isinstance(b, dict) and b.get("integration_id") == integration_id and b.get("notion_block_id") == notion_block_id:
                blk = b
                break

    if not blk:
        _log(False, integration_id, notion_endpoint=f"/v1/blocks/{notion_block_id or block_id}", notion_http_status=404, error_code="not_found", error_message="Block not found", request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id})
        return _err("NOT_FOUND", "Block not found")

    # Business rule: reject updates when blocks.status='deleted_remote'
    if blk.get("status") == "deleted_remote":
        _log(False, integration_id, notion_endpoint=f"/v1/blocks/{blk.get('notion_block_id')}", notion_http_status=404, error_code="deleted_remote", error_message="Cannot update a block marked deleted_remote", request_payload={"integration_id": integration_id})
        return _err("INVALID_TRANSITION", "Cannot update a block marked deleted_remote")

    # Apply updates
    if block_type is not None:
        blk["block_type"] = block_type
    if content is not None:
        # if a block_type is set/provided, accept the payload as passthrough
        blk["content"] = content
    if archived is not None:
        blk["archived"] = bool(archived)
        blk["status"] = "archived" if blk["archived"] else "active"

    blk["notion_last_edited_time"] = now
    blk["last_synced_at"] = now
    blk["last_sync_error"] = None
    blk["updated_at"] = now

    _save("blocks.json", blocks_store)
    _log(True, integration_id, notion_endpoint=f"/v1/blocks/{blk.get('notion_block_id')}", notion_http_status=200, request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id})
    return {"object": "block", "block": blk}

