        _log(False, integration_id, notion_endpoint=f"/v1/blocks/{notion_block_id or block_id}", notion_http_status=404, error_code="not_found", error_message="Block not found", request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id})
        return _err("NOT_FOUND", "Block not found")

    # Hard deletes are not allowed to preserve auditability
    if archive is False:
        _log(False, integration_id, error_code="invalid_transition", error_message="Hard deletes are not supported; only archiving is allowed", request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id, "archive": archive})
        return _err("INVALID_TRANSITION", "Hard deletes are not supported; only archiving is allowed")

    # Idempotent archive
    if blk.get("archived") is True and blk.get("status") == "archived":
        _log(True, integration_id, notion_endpoint=f"/v1/blocks/{blk.get('notion_block_id')}", notion_http_status=200, request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id, "archive": archive})
        return {"object": "block", "block": blk}

    blk["archived"] = True
    # lifecycle transition rules: active/sync_error -> archived OK; deleted_remote has no outgoing transitions, but local archive as "already gone" should be refused.
    if blk.get("status") == "deleted_remote":
        _log(False, integration_id, error_code="invalid_transition", error_message="Cannot archive a block marked deleted_remote", request_payload={"integration_id": integration_id})
        return _err("INVALID_TRANSITION", "Cannot archive a block marked deleted_remote")
    blk["status"] = "archived"
    blk["notion_last_edited_time"] = now
    blk["last_synced_at"] = now
    blk["last_sync_error"] = None
    blk["updated_at"] = now

    _save("blocks.json", blocks_store)
    _log(True, integration_id, notion_endpoint=f"/v1/blocks/{blk.get('notion_block_id')}", notion_http_status=200, request_payload={"integration_id": integration_id, "block_id": block_id, "notion_block_id": notion_block_id, "archive": archive})
    return {"object": "block", "block": blk}
